// smoelius: Based on: https://github.com/containers/bubblewrap/issues/142
// Thanks to @maxammann for the pointer.

macro_rules! i8_ptr {
    ($expr:expr) => {
        $expr as *const _ as *const i8
    };
}

fn main() {
    let cmd = "id\n";
    for c in cmd.chars() {
        if unsafe { libc::ioctl(libc::STDIN_FILENO, libc::TIOCSTI, i8_ptr!(&c)) } < 0 {
            unsafe { libc::perror(i8_ptr!(b"libc::ioctl\0")) };
            panic!();
        }
    }
}

use crate::util;

#[test]
fn dogfood() {
    let mut command = util::build_with_build_wrap();
    command.env("BUILD_WRAP_CMD", "time -p {}");

    let output = util::exec_forwarding_output(command, true).unwrap();
    let stderr = std::str::from_utf8(&output.stderr).unwrap();
    let lines = stderr.lines().collect::<Vec<_>>();
    assert!(
        lines.windows(3).any(|w| {
            assert_eq!(3, w.len());
            w[0].contains("] real ") && w[1].contains("] user ") && w[2].contains("] sys")
        }),
        "failed to find `time` output"
    );
}

