#[test]
fn build_scripts() {
    config::for_each_test_case(
        "tests/build_scripts",
        |name, build_wrap_cmd, path, stderr| {
            #[allow(clippy::explicit_write)]
            writeln!(
                std::io::stderr(),
                "running `{name}` build script test: {}",
                path.display()
