            .unwrap();

            test_case(build_wrap_cmd, &TestCase::BuildScript(path), stderr);

            Ok(())
        },
    )
    .unwrap();
}

use crate::util;

#[test]
fn allow() {
    let temp_package = util::temp_package(Some("tests/build_scripts/ping.rs"), []).unwrap();

    for allow in [false, true] {
        let mut command = util::build_with_build_wrap();
        if allow {
            command.env("BUILD_WRAP_ALLOW", "1");
        }
        command.current_dir(&temp_package);

        let output = util::exec_forwarding_output(command, false).unwrap();
        // smoelius: The command should succeed precisely when `BUILD_WRAP_ALLOW` is enabled.
        assert_eq!(allow, output.status.success());
        let stderr = std::str::from_utf8(&output.stderr).unwrap();
        assert!(stderr.contains("command failed"));
    }
}

use std::{
    env,
    net::{Ipv4Addr, SocketAddrV4, TcpStream},
    process::exit,
    time::Duration,
};

fn main() {
    let port = env::var("BUILD_WRAP_TCP_PORT")
        .ok()
        .and_then(|value| value.parse::<u16>().ok())
        .unwrap_or_else(|| {
            eprintln!("BUILD_WRAP_TCP_PORT is undefined or invalid");
            exit(1);
        });

    let address = SocketAddrV4::new(Ipv4Addr::LOCALHOST, port);

    if let Err(error) = TcpStream::connect_timeout(&address.into(), Duration::from_secs(1)) {
        eprintln!("failed to connect to {address}: {error}");
        exit(1);
    }
}

